import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, length, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry,
    DirectionalLight, PointLight, MathUtils,
  } = ctx.THREE;

  const root = new Group();
  root.name = 'orrery-mechanism';
  const stage = new Group(); // inner group so entrance motion never fights adapter placement
  root.add(stage);

  const disposables = [];
  const timelines = [];
  const primRecs = [];
  let tickerFn = null;

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 plane at z=-3, vertical gradient per spec stops
  // ---------------------------------------------------------------
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    const g0 = color('#0b0b10');
    const g1 = color('#101017');
    const g2 = color('#16161d');
    // subtle radial lift behind the mechanism so metal has tone to sit against
    const d = length(uv().sub(vec2(0.5, 0.55)));
    const base = mix(mix(g0, g1, smoothstep(0.0, 0.65, t)), g2, smoothstep(0.65, 1.0, t));
    const lift = color('#1b1b24');
    bgMat.colorNode = mix(base, lift, smoothstep(0.55, 0.0, d).mul(float(0.5)));
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -3);
  stage.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL LIGHTS — accent rim + cool back rim (scene has key/ambient)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight('#ff2a38', 1.1);
  rim.position.set(-3.2, 1.6, -2.0);
  stage.add(rim);

  const backFill = new DirectionalLight('#e8ecf2', 0.6);
  backFill.position.set(2.6, -1.2, -2.4);
  stage.add(backFill);

  const jewelGlow = new PointLight('#ff2a38', 0.7, 3.5, 2);
  jewelGlow.position.set(0, 0, 0.4);
  stage.add(jewelGlow);

  // ---------------------------------------------------------------
  // MATERIALS
  // ---------------------------------------------------------------
  const steelMat = new MeshPhysicalNodeMaterial({
    color: '#aab2bc',
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  steelMat.anisotropy = 0.7;
  steelMat.anisotropyRotation = Math.PI / 2; // radial-ish catch on spokes
  disposables.push(steelMat);

  const jewelMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    roughness: 0.15,
    metalness: 0.0,
    transmission: 0.6,
    ior: 1.76,
    thickness: 0.12,
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
  });
  disposables.push(jewelMat);

  const inkMat = new MeshPhysicalNodeMaterial({
    color: '#16161d',
    roughness: 0.55,
    metalness: 0.4,
  });
  disposables.push(inkMat);

  // ---------------------------------------------------------------
  // GEAR PIVOTS (phase-locked 16:9 mesh, primary 0.08 / secondary -0.142)
  // ---------------------------------------------------------------
  const primaryPivot = new Group();
  primaryPivot.position.set(0, 0, 0);
  stage.add(primaryPivot);

  const secondaryPivot = new Group();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  secondaryPivot.rotation.z = Math.PI / 9; // phase offset so teeth interleave
  stage.add(secondaryPivot);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;

    const source = gltf.scene;
    // normalize to 1.6-unit diameter in xy
    const box = new ctx.THREE.Box3().setFromObject(source);
    const size = new ctx.THREE.Vector3();
    box.getSize(size);
    const diameter = Math.max(size.x, size.y) || 1;
    const center = new ctx.THREE.Vector3();
    box.getCenter(center);

    const primary = source;
    primary.traverse((o) => {
      if (o.isMesh) o.material = steelMat;
    });
    const sP = 1.6 / diameter;
    primary.scale.setScalar(sP);
    primary.position.set(-center.x * sP, -center.y * sP, -center.z * sP);
    primaryPivot.add(primary);

    const secondary = primary.clone(true);
    const sS = 0.9 / diameter;
    secondary.scale.setScalar(sS);
    secondary.position.set(-center.x * sS, -center.y * sS, -center.z * sS);
    secondaryPivot.add(secondary);
  });

  // Jewel pivot at primary hub — the single brightest element on stage
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.12);
  stage.add(jewel);
  disposables.push(jewelGeo);

  // Arbor shafts through both hubs (z-length 0.8, radius 0.05, ink)
  const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 20);
  disposables.push(arborGeo);
  const arborA = new Mesh(arborGeo, inkMat);
  arborA.rotation.x = Math.PI / 2;
  arborA.position.set(0, 0, -0.1);
  stage.add(arborA);
  const arborB = new Mesh(arborGeo, inkMat);
  arborB.rotation.x = Math.PI / 2;
  arborB.position.set(1.15, 0.35, -0.2);
  stage.add(arborB);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — 2.6 x 1.2 ellipse at y=-1.2, opacity 0.5
  // ---------------------------------------------------------------
  const shGeo = new PlaneGeometry(2.6, 1.2);
  const shMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shMat.colorNode = color('#000000');
  {
    const d = length(uv().sub(vec2(0.5, 0.5)));
    shMat.opacityNode = smoothstep(0.5, 0.05, d).mul(float(0.5));
  }
  const shadow = new Mesh(shGeo, shMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0.35, -1.2, 0);
  stage.add(shadow);
  disposables.push(shGeo, shMat);

  // ---------------------------------------------------------------
  // TEXT — verbatim spec copy, bimodal scale
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;
    if (item.role === 'headline') {
      const h = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: '#e8ecf2',
        align: 'center',
      });
      h.position.set(0, -1.7, 0.4);
      stage.add(h);
    } else {
      const c = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 1.5,
      });
      c.position.set(0, -2.1, 0.4);
      stage.add(c);
    }
  }

  // ---------------------------------------------------------------
  // MOTION — meshed rotation ticker + weighted entrance
  // ---------------------------------------------------------------
  tickerFn = (time, deltaMs) => {
    const dt = Math.min(deltaMs / 1000, 0.1);
    primaryPivot.rotation.z += 0.08 * dt;
    secondaryPivot.rotation.z -= 0.142 * dt;
  };
  gsap.ticker.add(tickerFn);

  stage.position.y -= 0.35;
  const enter = gsap.timeline();
  enter.to(stage.position, { y: stage.position.y + 0.35, duration: 0.8, ease: 'power3.out' });
  enter.fromTo(
    stage.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.4, ease: 'power2.out' },
    0
  );
  enter.to(stage.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.4);
  timelines.push(enter);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const rec = fn(root, prim.params ?? {});
      if (rec) primRecs.push(rec);
    }
  }

  // ---------------------------------------------------------------
  // HANDLERS + CLEANUP
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (tickerFn) gsap.ticker.remove(tickerFn);
    for (const tl of timelines) tl.kill();
    for (const rec of primRecs) {
      if (rec.timeline) rec.timeline.kill?.();
      rec.cleanup?.();
    }
    root.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
      }
    });
    for (const d of disposables) d.dispose?.();
  };

  return root;
}
